E,sBAAA,CAGF,qEAEE,cAAA,CAGF,2DAEE,yBAAA,CAGF,0BACE,eAAA,CAGF,4BACE,aAAA,CACA,cAAA,CAGF,6BACE,YAAA,CAGF,+BACE,eAAA,CAGF,uCACE,6CAAA,CAGF,8FAEE,kBAAA,CAGF,gCACE,aAAA,CAAA,CAKJ,uCACE,qEAGE,mCAAA,CACA,6BAAA,CACA,sCAAA,CACA,+BAAA,CACA,oCAAA,CACA,8BAAA,CAAA","sourcesContent":["\n\n.opening-shell {\n  --ink: #4f3e46;\n  --muted: #8d737d;\n  --line: #ead8dc;\n  --soft-line: #f2e7e8;\n  --paper: #fffdfb;\n  --pink: #d9899e;\n  --pink-deep: #a95773;\n  --pink-soft: #fbecef;\n  --sage: #8ba59c;\n  --cream: #fff6ed;\n  position: relative;\n  isolation: isolate;\n  width: min(100%, 780px);\n  min-height: 100vh;\n  margin: 0 auto;\n  overflow: hidden;\n  padding: 30px 24px 24px;\n  background: #fffaf8;\n}\n.opening-shell {\n\n* {\n  box-sizing: border-box;\n}\n\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n}\n\n\nbutton {\n  cursor: pointer;\n}\n\n\n.ambient {\n  position: absolute;\n  z-index: -1;\n  width: 150px;\n  height: 150px;\n  border: 1px solid rgba(217, 137, 158, 0.22);\n  border-radius: 50%;\n  pointer-events: none;\n  animation: float-slow 20s ease-in-out infinite;\n}\n\n\n.ambient-one {\n  top: 110px;\n  right: -70px;\n}\n\n\n.ambient-two {\n  bottom: 120px;\n  left: -95px;\n  width: 190px;\n  height: 190px;\n  border-color: rgba(139, 165, 156, 0.22);\n  animation-delay: -3s;\n}\n\n\n.ornament-top {\n  position: absolute;\n  top: 16px;\n  right: 28px;\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  color: var(--pink);\n  font-family: Georgia, serif;\n  font-size: 12px;\n  letter-spacing: 0;\n  opacity: 0.75;\n}\n\n\n.ornament-top i {\n  display: block;\n  width: 22px;\n  height: 1px;\n  background: var(--line);\n}\n\n\n.opening-header {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  min-width: 0;\n  padding: 16px 4px 28px;\n}\n\n\n.brand-mark {\n  position: relative;\n  flex: 0 0 58px;\n  width: 58px;\n  height: 58px;\n  color: var(--pink-deep);\n}\n\n\n.brand-star,\n.brand-heart {\n  position: absolute;\n  display: block;\n  font-family: Georgia, serif;\n}\n\n\n.brand-star {\n  top: -4px;\n  left: 3px;\n  color: var(--sage);\n  font-size: 16px;\n  animation: twinkle 16s ease-in-out infinite;\n}\n\n\n.brand-heart {\n  right: 2px;\n  bottom: -2px;\n  font-size: 42px;\n  line-height: 1;\n  animation: breathe 18s ease-in-out infinite;\n}\n\n\n.brand-ring {\n  position: absolute;\n  top: 14px;\n  left: 11px;\n  width: 31px;\n  height: 31px;\n  border: 1px solid var(--pink);\n  border-radius: 50%;\n}\n\n\n.brand-copy {\n  min-width: 0;\n}\n\n\n.eyebrow {\n  margin: 0 0 5px;\n  color: var(--pink-deep);\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.16em;\n  line-height: 1.4;\n}\n\n\nh1,\nh2,\nh3,\np {\n  overflow-wrap: anywhere;\n}\n\n\nh1 {\n  margin: 0;\n  color: var(--ink);\n  font-family: Georgia, 'Songti SC', serif;\n  font-size: 31px;\n  font-weight: 500;\n  line-height: 1.15;\n}\n\n\n.subtitle {\n  margin: 7px 0 0;\n  color: var(--muted);\n  font-size: 12px;\n  line-height: 1.6;\n}\n\n\n.world-note {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  margin-left: auto;\n  padding: 7px 10px;\n  border: 1px solid var(--line);\n  color: var(--muted);\n  font-size: 10px;\n  line-height: 1.3;\n  white-space: nowrap;\n}\n\n\n.note-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--sage);\n  box-shadow: 0 0 0 3px rgba(139, 165, 156, 0.14);\n}\n\n\n.stepper {\n  display: flex;\n  gap: 0;\n  /* 与面板上缘咬合：页签条看上去是压在表格纸上的一排页签 */\n  margin-bottom: -1px;\n  padding: 0;\n  border: 1px solid var(--line);\n  border-bottom: none;\n  border-radius: 12px 12px 0 0;\n  background: #f4ebec;\n  overflow: visible;\n}\n\n\n.step-item {\n  display: flex;\n  flex: 1 1 0;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  min-width: 0;\n  min-height: 40px;\n  padding: 9px 6px;\n  border: 0;\n  border-right: 1px solid var(--line);\n  border-radius: 10px 10px 0 0;\n  background: transparent;\n  color: #a48b93;\n  font-size: 11px;\n  position: relative;\n  transition: color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;\n}\n\n\n.step-item:last-child {\n  border-right: 0;\n}\n\n\n.step-item:hover,\n.step-item:focus-visible {\n  color: var(--pink-deep);\n  outline: none;\n  background: #fff7f6;\n}\n\n\n.step-item.active {\n  background: var(--paper);\n  color: var(--pink-deep);\n  /* 当前页签微微上抬，与下方的表格纸接上 */\n  transform: translateY(-1px);\n  box-shadow: 0 -3px 12px rgba(148, 91, 111, 0.09);\n  z-index: 2;\n}\n\n\n.step-item.done {\n  color: var(--sage);\n}\n\n\n.step-number {\n  display: grid;\n  place-items: center;\n  flex: 0 0 20px;\n  width: 20px;\n  height: 20px;\n  border: 1px solid currentColor;\n  /* 方章而不是圆点：序号也是一枚印 */\n  border-radius: 3px;\n  font-size: 9px;\n  line-height: 1;\n}\n\n\n.step-item.done .step-number {\n  background: var(--sage);\n  border-color: var(--sage);\n  color: #fff;\n}\n\n\n.step-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n\n.form-panel,\n.locked-panel {\n  position: relative;\n  border: 1px solid var(--line);\n  background: var(--paper);\n  box-shadow: 0 12px 28px rgba(148, 91, 111, 0.08);\n}\n\n\n.form-panel {\n  padding: 28px 30px 20px;\n  border-radius: 0 0 14px 14px;\n}\n\n\n.form-panel::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: 20px;\n  width: 1px;\n  /* 装订线的针脚虚线：整张表像被装订过 */\n  background: repeating-linear-gradient(180deg, rgba(217, 137, 158, 0.42) 0 4px, transparent 4px 10px);\n  pointer-events: none;\n}\n\n\n.panel-heading {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 20px;\n  padding-bottom: 18px;\n  border-bottom: 1px solid var(--soft-line);\n  /* 表头的双线：一条实线加一条更淡的副线 */\n  box-shadow: 0 4px 0 -3px var(--soft-line);\n}\n\n\n.panel-heading h2,\n.locked-panel h2 {\n  margin: 0;\n  color: var(--ink);\n  font-family: Georgia, 'Songti SC', serif;\n  font-size: 25px;\n  font-weight: 500;\n  line-height: 1.3;\n}\n\n\n.heading-description {\n  max-widt